<?php
$cv=$cv??[];$educations=$educations??[];$workHistories=$workHistories??[];$certificatesOfCv=$certificatesOfCv??[];$skillsOfCv=$skillsOfCv??[];
$h=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');
$pick=function($r,$keys,$d=''){foreach((array)$keys as $k){if(isset($r[$k])&&$r[$k]!=='')return $r[$k];}return $d;};
$name=$pick($cv,['full_name','name'],'Untitled CV');$id=$pick($cv,['id','cv_id'],'');
$category=$pick($cv,['category_name','category'],'Online CV');
$email=$pick($cv,'email');$phone=$pick($cv,['phone_number','phone']);$dob=$pick($cv,['date_of_birth','dob']);$gender=$pick($cv,'gender');
$address=implode(', ',array_filter([$pick($cv,['street_address','address']),$pick($cv,['district_name','district']),$pick($cv,['city_name','city']),$pick($cv,['country_name','country']),$pick($cv,'postal_code')]));
$period=fn($r)=>trim(($pick($r,'start_year')?:'').' - '.($pick($r,'end_year')?:'Present'));
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Classic CV</title><style>
:root{--ink:#211b16;--muted:#776b61;--line:#ded5cc;--accent:#8b5e34;--soft:#fbf7f2}*{box-sizing:border-box}body{margin:0;background:#edeff3;font-family:Georgia,'Times New Roman',serif;color:var(--ink)}.page{width:min(940px,calc(100% - 32px));margin:30px auto;background:white;padding:52px 60px;box-shadow:0 25px 70px rgba(31,41,55,.14);border:1px solid #e7e0d9}.top{text-align:center;border-bottom:4px double var(--line);padding-bottom:24px}.eyebrow{letter-spacing:4px;text-transform:uppercase;color:var(--accent);font-size:12px;font-weight:800;margin-bottom:12px}h1{font-size:46px;line-height:1;margin:0;text-transform:uppercase;letter-spacing:1px}.role{margin-top:10px;color:var(--muted);font-style:italic}.contact{display:flex;flex-wrap:wrap;gap:10px 22px;justify-content:center;margin-top:20px;color:var(--muted);font-size:14px}.actions{display:flex;justify-content:center;gap:12px;flex-wrap:wrap;margin:20px 0}.actions a{text-decoration:none;border-radius:999px;padding:10px 16px;font:700 13px Arial;color:white;background:var(--accent)}.actions a.secondary{background:var(--soft);color:var(--accent);border:1px solid var(--line)}.summary{margin:28px 0;padding:18px 22px;background:var(--soft);border-left:6px solid var(--accent);line-height:1.7}.layout{display:grid;grid-template-columns:1.2fr .75fr;gap:36px}.section{margin-bottom:30px}.title{display:flex;align-items:center;gap:12px;color:var(--accent);text-transform:uppercase;letter-spacing:2px;font:800 14px Arial;margin-bottom:16px}.title:after{content:"";height:1px;background:var(--line);flex:1}.entry{border-left:1px solid var(--line);padding:0 0 20px 18px;margin-left:7px;position:relative}.entry:before{content:"";position:absolute;left:-5px;top:4px;width:9px;height:9px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 5px var(--soft)}.entry h3{margin:0;font-size:18px}.meta{font-size:13px;color:var(--muted);font-style:italic;margin:5px 0 8px}.desc{font-size:14px;line-height:1.65}.sidebox{border:1px solid var(--line);background:#fcfbfa;padding:18px;margin-bottom:18px}.info{border-bottom:1px solid #eee3d8;padding:10px 0;font-size:14px}.info:last-child{border-bottom:0}.chips{display:flex;flex-wrap:wrap;gap:8px}.chip{border:1px solid var(--line);background:var(--soft);padding:8px 11px;border-radius:999px;font-size:13px}.empty{color:var(--muted);font-style:italic}@media(max-width:760px){.page{padding:36px 24px}.layout{grid-template-columns:1fr}h1{font-size:34px}}
</style></head><body><div class="page"><header class="top"><div class="eyebrow"><?= $h($category) ?></div><h1><?= $h($name) ?></h1><div class="role">Classic Professional Resume</div><div class="contact"><?php if($email):?><span><?= $h($email) ?></span><?php endif;?><?php if($phone):?><span><?= $h($phone) ?></span><?php endif;?><?php if($address):?><span><?= $h($address) ?></span><?php endif;?></div></header><div class="actions"><a class="secondary" href="?route=seeker/cv/templates<?= $id?'&id='.$h($id):'' ?>">Change Template</a><a href="?route=seeker/cv/edit">Edit CV</a></div><?php if(!empty($cv['summary'])):?><div class="summary"><?= nl2br($h($cv['summary'])) ?></div><?php endif;?><main class="layout"><section><div class="section"><div class="title">Education</div><?php if($educations): foreach($educations as $e):?><article class="entry"><h3><?= $h($pick($e,['degree_name','degree','degree_level_name'],'Education')) ?></h3><div class="meta"><?= $h(implode(' · ',array_filter([$pick($e,['institution_name','institution']),$pick($e,['major_name','major']),$period($e)]))) ?></div><?php if($pick($e,'description')):?><div class="desc"><?= nl2br($h($pick($e,'description'))) ?></div><?php endif;?></article><?php endforeach; else:?><p class="empty">No education records.</p><?php endif;?></div><div class="section"><div class="title">Work History</div><?php if($workHistories): foreach($workHistories as $w):?><article class="entry"><h3><?= $h($pick($w,['job_title_name','job_title'],'Work Experience')) ?></h3><div class="meta"><?= $h(implode(' · ',array_filter([$pick($w,'company_name'),$pick($w,['employment_type_name','employment_type']),$pick($w,['industry_name','industry']),$period($w)]))) ?></div><?php if($pick($w,['job_description','description'])):?><div class="desc"><?= nl2br($h($pick($w,['job_description','description']))) ?></div><?php endif;?></article><?php endforeach; else:?><p class="empty">No work history records.</p><?php endif;?></div></section><aside><div class="sidebox"><div class="title">Profile</div><?php foreach(['Email'=>$email,'Phone'=>$phone,'Date of Birth'=>$dob,'Gender'=>$gender,'Address'=>$address] as $k=>$v): if($v):?><div class="info"><strong><?= $h($k) ?></strong><br><?= $h($v) ?></div><?php endif; endforeach;?></div><div class="sidebox"><div class="title">Skills</div><div class="chips"><?php if($skillsOfCv): foreach($skillsOfCv as $s):?><span class="chip"><?= $h($pick($s,['skill_name','skill'],'Skill')) ?><?php if($pick($s,['proficiency_name','proficiency'])):?> · <?= $h($pick($s,['proficiency_name','proficiency'])) ?><?php endif;?></span><?php endforeach; else:?><span class="empty">No skills.</span><?php endif;?></div></div><div class="sidebox"><div class="title">Certificates</div><?php if($certificatesOfCv): foreach($certificatesOfCv as $c):?><div class="info"><strong><?= $h($pick($c,['certificate_name','certificate'],'Certificate')) ?></strong><br><?= $h(implode(' · ',array_filter([$pick($c,['organization_name','organization']),$pick($c,'year_issued')]))) ?></div><?php endforeach; else:?><p class="empty">No certificates.</p><?php endif;?></div></aside></main></div></body></html>
